macro_rules! impl_23 {
    () => {
        deps!();
        impl < 'a > DFA < & 'a [u32] > { # [doc = " Safely deserialize a DFA with a specific state identifier"] # [doc = " representation. Upon success, this returns both the deserialized DFA"] # [doc = " and the number of bytes read from the given slice. Namely, the contents"] # [doc = " of the slice beyond the DFA are not read."] # [doc = ""] # [doc = " Deserializing a DFA using this routine will never allocate heap memory."] # [doc = " For safety purposes, the DFA's transition table will be verified such"] # [doc = " that every transition points to a valid state. If this verification is"] # [doc = " too costly, then a [`DFA::from_bytes_unchecked`] API is provided, which"] # [doc = " will always execute in constant time."] # [doc = ""] # [doc = " The bytes given must be generated by one of the serialization APIs"] # [doc = " of a `DFA` using a semver compatible release of this crate. Those"] # [doc = " include:"] # [doc = ""] # [doc = " * [`DFA::to_bytes_little_endian`]"] # [doc = " * [`DFA::to_bytes_big_endian`]"] # [doc = " * [`DFA::to_bytes_native_endian`]"] # [doc = " * [`DFA::write_to_little_endian`]"] # [doc = " * [`DFA::write_to_big_endian`]"] # [doc = " * [`DFA::write_to_native_endian`]"] # [doc = ""] # [doc = " The `to_bytes` methods allocate and return a `Vec<u8>` for you, along"] # [doc = " with handling alignment correctly. The `write_to` methods do not"] # [doc = " allocate and write to an existing slice (which may be on the stack)."] # [doc = " Since deserialization always uses the native endianness of the target"] # [doc = " platform, the serialization API you use should match the endianness of"] # [doc = " the target platform. (It's often a good idea to generate serialized"] # [doc = " DFAs for both forms of endianness and then load the correct one based"] # [doc = " on endianness.)"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Generally speaking, it's easier to state the conditions in which an"] # [doc = " error is _not_ returned. All of the following must be true:"] # [doc = ""] # [doc = " * The bytes given must be produced by one of the serialization APIs"] # [doc = "   on this DFA, as mentioned above."] # [doc = " * The endianness of the target platform matches the endianness used to"] # [doc = "   serialized the provided DFA."] # [doc = " * The slice given must have the same alignment as `u32`."] # [doc = ""] # [doc = " If any of the above are not true, then an error will be returned."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This routine will never panic for any input."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to serialize a DFA to raw bytes, deserialize it"] # [doc = " and then use it for searching."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, dense::DFA}, HalfMatch, Input};"] # [doc = ""] # [doc = " let initial = DFA::new(\"foo[0-9]+\")?;"] # [doc = " let (bytes, _) = initial.to_bytes_native_endian();"] # [doc = " let dfa: DFA<&[u32]> = DFA::from_bytes(&bytes)?.0;"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(0, 8));"] # [doc = " assert_eq!(expected, dfa.try_search_fwd(&Input::new(\"foo12345\"))?);"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: dealing with alignment and padding"] # [doc = ""] # [doc = " In the above example, we used the `to_bytes_native_endian` method to"] # [doc = " serialize a DFA, but we ignored part of its return value corresponding"] # [doc = " to padding added to the beginning of the serialized DFA. This is OK"] # [doc = " because deserialization will skip this initial padding. What matters"] # [doc = " is that the address immediately following the padding has an alignment"] # [doc = " that matches `u32`. That is, the following is an equivalent but"] # [doc = " alternative way to write the above example:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, dense::DFA}, HalfMatch, Input};"] # [doc = ""] # [doc = " let initial = DFA::new(\"foo[0-9]+\")?;"] # [doc = " // Serialization returns the number of leading padding bytes added to"] # [doc = " // the returned Vec<u8>."] # [doc = " let (bytes, pad) = initial.to_bytes_native_endian();"] # [doc = " let dfa: DFA<&[u32]> = DFA::from_bytes(&bytes[pad..])?.0;"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(0, 8));"] # [doc = " assert_eq!(expected, dfa.try_search_fwd(&Input::new(\"foo12345\"))?);"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " This padding is necessary because Rust's standard library does"] # [doc = " not expose any safe and robust way of creating a `Vec<u8>` with a"] # [doc = " guaranteed alignment other than 1. Now, in practice, the underlying"] # [doc = " allocator is likely to provide a `Vec<u8>` that meets our alignment"] # [doc = " requirements, which means `pad` is zero in practice most of the time."] # [doc = ""] # [doc = " The purpose of exposing the padding like this is flexibility for the"] # [doc = " caller. For example, if one wants to embed a serialized DFA into a"] # [doc = " compiled program, then it's important to guarantee that it starts at a"] # [doc = " `u32`-aligned address. The simplest way to do this is to discard the"] # [doc = " padding bytes and set it up so that the serialized DFA itself begins at"] # [doc = " a properly aligned address. We can show this in two parts. The first"] # [doc = " part is serializing the DFA to a file:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use regex_automata::dfa::dense::DFA;"] # [doc = ""] # [doc = " let dfa = DFA::new(\"foo[0-9]+\")?;"] # [doc = ""] # [doc = " let (bytes, pad) = dfa.to_bytes_big_endian();"] # [doc = " // Write the contents of the DFA *without* the initial padding."] # [doc = " std::fs::write(\"foo.bigendian.dfa\", &bytes[pad..])?;"] # [doc = ""] # [doc = " // Do it again, but this time for little endian."] # [doc = " let (bytes, pad) = dfa.to_bytes_little_endian();"] # [doc = " std::fs::write(\"foo.littleendian.dfa\", &bytes[pad..])?;"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " And now the second part is embedding the DFA into the compiled program"] # [doc = " and deserializing it at runtime on first use. We use conditional"] # [doc = " compilation to choose the correct endianness."] # [doc = ""] # [doc = " ```no_run"] # [doc = " use regex_automata::{"] # [doc = "     dfa::{Automaton, dense::DFA},"] # [doc = "     util::{lazy::Lazy, wire::AlignAs},"] # [doc = "     HalfMatch, Input,"] # [doc = " };"] # [doc = ""] # [doc = " // This crate provides its own \"lazy\" type, kind of like"] # [doc = " // lazy_static! or once_cell::sync::Lazy. But it works in no-alloc"] # [doc = " // no-std environments and let's us write this using completely"] # [doc = " // safe code."] # [doc = " static RE: Lazy<DFA<&'static [u32]>> = Lazy::new(|| {"] # [doc = "     # const _: &str = stringify! {"] # [doc = "     // This assignment is made possible (implicitly) via the"] # [doc = "     // CoerceUnsized trait. This is what guarantees that our"] # [doc = "     // bytes are stored in memory on a 4 byte boundary. You"] # [doc = "     // *must* do this or something equivalent for correct"] # [doc = "     // deserialization."] # [doc = "     static ALIGNED: &AlignAs<[u8], u32> = &AlignAs {"] # [doc = "         _align: [],"] # [doc = "         #[cfg(target_endian = \"big\")]"] # [doc = "         bytes: *include_bytes!(\"foo.bigendian.dfa\"),"] # [doc = "         #[cfg(target_endian = \"little\")]"] # [doc = "         bytes: *include_bytes!(\"foo.littleendian.dfa\"),"] # [doc = "     };"] # [doc = "     # };"] # [doc = "     # static ALIGNED: &AlignAs<[u8], u32> = &AlignAs {"] # [doc = "     #     _align: [],"] # [doc = "     #     bytes: [],"] # [doc = "     # };"] # [doc = ""] # [doc = "     let (dfa, _) = DFA::from_bytes(&ALIGNED.bytes)"] # [doc = "         .expect(\"serialized DFA should be valid\");"] # [doc = "     dfa"] # [doc = " });"] # [doc = ""] # [doc = " let expected = Ok(Some(HalfMatch::must(0, 8)));"] # [doc = " assert_eq!(expected, RE.try_search_fwd(&Input::new(\"foo12345\")));"] # [doc = " ```"] # [doc = ""] # [doc = " An alternative to [`util::lazy::Lazy`](crate::util::lazy::Lazy)"] # [doc = " is [`lazy_static`](https://crates.io/crates/lazy_static) or"] # [doc = " [`once_cell`](https://crates.io/crates/once_cell), which provide"] # [doc = " stronger guarantees (like the initialization function only being"] # [doc = " executed once). And `once_cell` in particular provides a more"] # [doc = " expressive API. But a `Lazy` value from this crate is likely just fine"] # [doc = " in most circumstances."] # [doc = ""] # [doc = " Note that regardless of which initialization method you use, you"] # [doc = " will still need to use the [`AlignAs`](crate::util::wire::AlignAs)"] # [doc = " trick above to force correct alignment, but this is safe to do and"] # [doc = " `from_bytes` will return an error if you get it wrong."] pub fn from_bytes (slice : & 'a [u8] ,) -> Result < (DFA < & 'a [u32] > , usize) , DeserializeError > { let (dfa , nread) = unsafe { DFA :: from_bytes_unchecked (slice) ? } ; dfa . accels . validate () ? ; dfa . ms . validate (& dfa) ? ; dfa . tt . validate (& dfa) ? ; dfa . st . validate (& dfa) ? ; for state in dfa . states () { if dfa . is_accel_state (state . id ()) { let index = dfa . accelerator_index (state . id ()) ; if index >= dfa . accels . len () { return Err (DeserializeError :: generic ("found DFA state with invalid accelerator index" ,)) ; } let needles = dfa . accels . needles (index) ; if ! (1 <= needles . len () && needles . len () <= 3) { return Err (DeserializeError :: generic ("accelerator needles has invalid length" ,)) ; } } } Ok ((dfa , nread)) } # [doc = " Deserialize a DFA with a specific state identifier representation in"] # [doc = " constant time by omitting the verification of the validity of the"] # [doc = " transition table and other data inside the DFA."] # [doc = ""] # [doc = " This is just like [`DFA::from_bytes`], except it can potentially return"] # [doc = " a DFA that exhibits undefined behavior if its transition table contains"] # [doc = " invalid state identifiers."] # [doc = ""] # [doc = " This routine is useful if you need to deserialize a DFA cheaply"] # [doc = " and cannot afford the transition table validation performed by"] # [doc = " `from_bytes`."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{dfa::{Automaton, dense::DFA}, HalfMatch, Input};"] # [doc = ""] # [doc = " let initial = DFA::new(\"foo[0-9]+\")?;"] # [doc = " let (bytes, _) = initial.to_bytes_native_endian();"] # [doc = " // SAFETY: This is guaranteed to be safe since the bytes given come"] # [doc = " // directly from a compatible serialization routine."] # [doc = " let dfa: DFA<&[u32]> = unsafe { DFA::from_bytes_unchecked(&bytes)?.0 };"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(0, 8));"] # [doc = " assert_eq!(expected, dfa.try_search_fwd(&Input::new(\"foo12345\"))?);"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub unsafe fn from_bytes_unchecked (slice : & 'a [u8] ,) -> Result < (DFA < & 'a [u32] > , usize) , DeserializeError > { let mut nr = 0 ; nr += wire :: skip_initial_padding (slice) ; wire :: check_alignment :: < StateID > (& slice [nr ..]) ? ; nr += wire :: read_label (& slice [nr ..] , LABEL) ? ; nr += wire :: read_endianness_check (& slice [nr ..]) ? ; nr += wire :: read_version (& slice [nr ..] , VERSION) ? ; let _unused = wire :: try_read_u32 (& slice [nr ..] , "unused space") ? ; nr += size_of :: < u32 > () ; let (flags , nread) = Flags :: from_bytes (& slice [nr ..]) ? ; nr += nread ; let (tt , nread) = TransitionTable :: from_bytes_unchecked (& slice [nr ..]) ? ; nr += nread ; let (st , nread) = StartTable :: from_bytes_unchecked (& slice [nr ..]) ? ; nr += nread ; let (ms , nread) = MatchStates :: from_bytes_unchecked (& slice [nr ..]) ? ; nr += nread ; let (special , nread) = Special :: from_bytes (& slice [nr ..]) ? ; nr += nread ; special . validate_state_len (tt . len () , tt . stride2) ? ; let (accels , nread) = Accels :: from_bytes_unchecked (& slice [nr ..]) ? ; nr += nread ; let (quitset , nread) = ByteSet :: from_bytes (& slice [nr ..]) ? ; nr += nread ; let pre = None ; Ok ((DFA { tt , st , ms , special , accels , pre , quitset , flags } , nr)) } # [doc = " The implementation of the public `write_to` serialization methods,"] # [doc = " which is generic over endianness."] # [doc = ""] # [doc = " This is defined only for &[u32] to reduce binary size/compilation time."] fn write_to < E : Endian > (& self , mut dst : & mut [u8] ,) -> Result < usize , SerializeError > { let nwrite = self . write_to_len () ; if dst . len () < nwrite { return Err (SerializeError :: buffer_too_small ("dense DFA")) ; } dst = & mut dst [.. nwrite] ; let mut nw = 0 ; nw += wire :: write_label (LABEL , & mut dst [nw ..]) ? ; nw += wire :: write_endianness_check :: < E > (& mut dst [nw ..]) ? ; nw += wire :: write_version :: < E > (VERSION , & mut dst [nw ..]) ? ; nw += { E :: write_u32 (0 , & mut dst [nw ..]) ; size_of :: < u32 > () } ; nw += self . flags . write_to :: < E > (& mut dst [nw ..]) ? ; nw += self . tt . write_to :: < E > (& mut dst [nw ..]) ? ; nw += self . st . write_to :: < E > (& mut dst [nw ..]) ? ; nw += self . ms . write_to :: < E > (& mut dst [nw ..]) ? ; nw += self . special . write_to :: < E > (& mut dst [nw ..]) ? ; nw += self . accels . write_to :: < E > (& mut dst [nw ..]) ? ; nw += self . quitset . write_to :: < E > (& mut dst [nw ..]) ? ; Ok (nw) } }
    };
}

